def buka_kamera(pilihan):
    """Coba beberapa nomor kamera dan backend; kamera virtual berlayar hitam dilewati saat mode Otomatis."""
    daftar = range(5) if pilihan == "Otomatis" else [int(pilihan)]
    for idx in daftar:
        for backend in (cv2.CAP_DSHOW, cv2.CAP_MSMF, cv2.CAP_ANY):
            cap = cv2.VideoCapture(idx, backend)
            if cap.isOpened():
                ok, frame = False, None
                for _ in range(8):
                    ok, frame = cap.read()
                if ok and frame is not None and (pilihan != "Otomatis" or frame.mean() > 8):
                    return cap, idx
            cap.release()
    return None, None


def b64(rgb):
    _, buf = cv2.imencode(".jpg", rgb[:, :, ::-1], [cv2.IMWRITE_JPEG_QUALITY, 90])
    return base64.b64encode(buf).decode()


