# Gantungan bisa ditarik bebas (kiri/kanan/atas/bawah), lepas -> mengayun balik seperti bandul
LY_JS = """<script>
const stage=document.getElementById('ly-stage'),wrap=document.getElementById('ly-wrap'),strap=document.getElementById('ly-strap');
const CW=280;let W=stage.clientWidth,H=stage.clientHeight;
let rest={x:W/2,y:170},p={x:rest.x,y:rest.y},v={x:0,y:0},drag=false,off={x:0,y:0},prev=null;
function layout(){
  const ax=W/2,ay=-6,dx=p.x-ax,dy=p.y-ay,len=Math.hypot(dx,dy),ang=-Math.atan2(dx,dy)*180/Math.PI;
  strap.style.left=(ax-14)+'px';strap.style.top=ay+'px';strap.style.height=len+'px';strap.style.transform='rotate('+ang+'deg)';
  const sway=Math.max(-14,Math.min(14,v.x*0.03));
  wrap.style.left=(p.x-CW/2)+'px';wrap.style.top=p.y+'px';wrap.style.transform='rotate('+(ang+sway)+'deg)';
}
function clamp(){p.x=Math.max(CW/2-60,Math.min(W-CW/2+60,p.x));p.y=Math.max(40,Math.min(H-120,p.y));}
function loop(){
  if(!drag){v.x=(v.x+(rest.x-p.x)*0.045)*0.9;v.y=(v.y+(rest.y-p.y)*0.045)*0.9;p.x+=v.x;p.y+=v.y;}
  layout();requestAnimationFrame(loop);
}
wrap.addEventListener('pointerdown',e=>{drag=true;wrap.classList.add('drag');wrap.setPointerCapture(e.pointerId);
  off={x:e.clientX-p.x,y:e.clientY-p.y};prev={x:p.x,y:p.y,t:performance.now()};v={x:0,y:0};});
wrap.addEventListener('pointermove',e=>{if(!drag)return;
  p.x=e.clientX-off.x;p.y=e.clientY-off.y;clamp();
  const n=performance.now(),dt=Math.max(1,n-prev.t);v.x=(p.x-prev.x)/dt*16;v.y=(p.y-prev.y)/dt*16;prev={x:p.x,y:p.y,t:n};});
const up=()=>{drag=false;wrap.classList.remove('drag');};
wrap.addEventListener('pointerup',up);wrap.addEventListener('pointercancel',up);
window.addEventListener('resize',()=>{W=stage.clientWidth;H=stage.clientHeight;rest.x=W/2;});
requestAnimationFrame(loop);
</script>"""


