# Tab kamera diletakkan paling akhir karena mode live berupa loop (tab lain tetap tampil lebih dulu)
with tab2:
    mode = st.radio("Mode kamera", ["🔴 Live real-time", "📸 Foto"], horizontal=True)
    k1, k2 = st.columns([2, 3])
    nyala = k1.toggle("📷 Nyalakan kamera", value=False, key="kamera_on")
    k2.markdown(f'<span class="pill {"on" if nyala else "off"}">● KAMERA {"AKTIF" if nyala else "MATI"}</span>',
                unsafe_allow_html=True)
    if not nyala:
        st.info("Kamera dimatikan agar laptop tetap ringan. Geser tombol di atas untuk menyalakan.")
    elif mode.startswith("📸"):
        foto = st.camera_input("Ambil foto dari kamera")
        if foto is not None:
            img = cv2.imdecode(np.frombuffer(foto.getvalue(), np.uint8), cv2.IMREAD_COLOR)
            tampilkan(img, time.strftime("kamera_%H%M%S.jpg"))
    else:
        pilihan = st.selectbox("Pilih kamera", ["Otomatis", "0", "1", "2", "3", "4"])
        conf_live = st.slider("Ketelitian kamera live (confidence)", 0.30, 0.90, 0.60, 0.05)
        min_hits = st.slider("Konfirmasi: minimal muncul di berapa dari 8 frame terakhir", 1, 8, 5)
        cap, idx_kamera = buka_kamera(pilihan)
        if cap is None:
            st.error("Kamera tidak ditemukan. Coba pilih nomor kamera lain di atas. Tutup aplikasi lain yang memakai kamera (Zoom/Meet), "
                     "cek izin kamera Windows, lalu coba lagi. Mode live hanya jalan saat web dijalankan di laptop yang punya kamera.")
        else:
            st.caption(f"Kamera #{idx_kamera} terbuka. Kotak baru muncul setelah terkonfirmasi beberapa frame (jeda sekitar 1 detik).")
            cap.set(cv2.CAP_PROP_FRAME_WIDTH, 640)
            cap.set(cv2.CAP_PROP_FRAME_HEIGHT, 480)
            tampil, info = st.empty(), st.empty()
            penstabil = Penstabil(8, min_hits)
            riwayat_status, fps, t_prev = deque(maxlen=8), 0.0, time.time()
            try:
                while True:
                    ok, frame = cap.read()
                    if not ok:
                        st.warning("Gagal membaca gambar dari kamera.")
                        break
                    hasil = analisis(model, frame, conf_live, imgsz, model_orang, penstabil)
                    st_frame, kurang = cek_kepatuhan(set(hasil["jumlah"]), wajib)
                    if hasil.get("jumlah_orang") == 0:
                        st_frame, kurang = "TIDAK ADA ORANG", []
                    riwayat_status.append(st_frame)
                    status = max(set(riwayat_status), key=list(riwayat_status).count)  # voting 8 frame, anti berkedip
                    now = time.time()
                    fps = 0.9 * fps + 0.1 / max(now - t_prev, 1e-3)
                    t_prev = now
                    tampil.image(hasil["gambar_hasil"], channels="RGB", width="stretch", output_format="JPEG")
                    warna = {"PATUH": HIJAU, "TIDAK PATUH": MERAH}.get(status, "#F2A900")
                    ket = " | belum terdeteksi: " + ", ".join(kurang) if status == "TIDAK PATUH" else ""
                    info.markdown(f'<div style="padding:12px 18px;border-radius:14px;background:{warna};color:#fff;'
                                  f'font-weight:700;font-size:1.2rem;text-align:center">'
                                  f'{LABEL[status]}{ket} &nbsp;•&nbsp; {fps:.1f} FPS</div>',
                                  unsafe_allow_html=True)
            finally:
                cap.release()


